CALL { WITH a MATCH (a)-[r:`A`]->(m:`Leaf`) RETURN count(CASE WHEN CASE WHEN r.`seenAt` IS :: ZONED DATETIME THEN r.`seenAt` WHEN r.`seenAt` IS :: LOCAL DATETIME THEN datetime({datetime: r.`seenAt`, timezone: 'UTC'}) WHEN r.`seenAt` IS :: DATE THEN datetime({date: r.`seenAt`, timezone: 'UTC'}) END >= datetime($windowFrom) AND CASE WHEN r.`seenAt` IS :: ZONED DATETIME THEN r.`seenAt` WHEN r.`seenAt` IS :: LOCAL DATETIME THEN datetime({datetime: r.`seenAt`, timezone: 'UTC'}) WHEN r.`seenAt` IS :: DATE THEN datetime({date: r.`seenAt`, timezone: 'UTC'}) END < datetime($windowTo) THEN r END) AS c, count(CASE WHEN CASE WHEN r.`seenAt` IS :: ZONED DATETIME THEN r.`seenAt` WHEN r.`seenAt` IS :: LOCAL DATETIME THEN datetime({datetime: r.`seenAt`, timezone: 'UTC'}) WHEN r.`seenAt` IS :: DATE THEN datetime({date: r.`seenAt`, timezone: 'UTC'}) END IS NULL THEN r END) AS u UNION ALL WITH a MATCH (a)-[r:`B`]->(m:`Leaf`) RETURN count(CASE WHEN CASE WHEN r.`seenAt` IS :: ZONED DATETIME THEN r.`seenAt` WHEN r.`seenAt` IS :: LOCAL DATETIME THEN datetime({datetime: r.`seenAt`, timezone: 'UTC'}) WHEN r.`seenAt` IS :: DATE THEN datetime({date: r.`seenAt`, timezone: 'UTC'}) END >= datetime($windowFrom) AND CASE WHEN r.`seenAt` IS :: ZONED DATETIME THEN r.`seenAt` WHEN r.`seenAt` IS :: LOCAL DATETIME THEN datetime({datetime: r.`seenAt`, timezone: 'UTC'}) WHEN r.`seenAt` IS :: DATE THEN datetime({date: r.`seenAt`, timezone: 'UTC'}) END < datetime($windowTo) THEN r END) AS c, count(CASE WHEN CASE WHEN r.`seenAt` IS :: ZONED DATETIME THEN r.`seenAt` WHEN r.`seenAt` IS :: LOCAL DATETIME THEN datetime({datetime: r.`seenAt`, timezone: 'UTC'}) WHEN r.`seenAt` IS :: DATE THEN datetime({date: r.`seenAt`, timezone: 'UTC'}) END IS NULL THEN r END) AS u UNION ALL WITH a MATCH (a)-[r:`C`]->(m:`Leaf`) RETURN count(r) AS c, 0 AS u }
RETURN sum(c) AS total, sum(u) AS undated
